import { MakeLogicType, actions, afterMount, connect, kea, key, listeners, path, props, reducers, selectors } from 'kea'
import type { DeepPartial } from 'kea-forms/lib/index'

import { toast } from '@hanzo/elements'

import api from 'lib/api'

import { InsightsFunctionConfigurationType } from '~/types'

import type { InsightsFunctionType } from '../../../types'
import { insightsFunctionConfigurationLogic } from '../configuration/insightsFunctionConfigurationLogic'

export interface InsightsFunctionBackfillsLogicProps {
    id: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface insightsFunctionBackfillsLogicValues {
    configuration: InsightsFunctionConfigurationType // insightsFunctionConfigurationLogic
    hasTriedEnabling: boolean
    isLoading: boolean
    isReady: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface insightsFunctionBackfillsLogicActions {
    loadInsightsFunction: () => any // insightsFunctionConfigurationLogic
    loadInsightsFunctionSuccess: (
        insightsFunction: InsightsFunctionType | null,
        payload?: any
    ) => {
        insightsFunction: InsightsFunctionType | null
        payload?: any
    } // insightsFunctionConfigurationLogic
    setConfigurationValues: (values: DeepPartial<InsightsFunctionConfigurationType>) => {
        values: DeepPartial<InsightsFunctionConfigurationType>
    } // insightsFunctionConfigurationLogic
    enableInsightsFunctionBackfills: () => boolean
    setLoading: (loading: boolean) => {
        loading: boolean
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface insightsFunctionBackfillsLogicMeta {
    key: string
    __keaTypeGenInternalSelectorTypes: {
        isReady: (configuration: InsightsFunctionConfigurationType, isLoading: boolean) => boolean
    }
}

export type insightsFunctionBackfillsLogicType = MakeLogicType<
    insightsFunctionBackfillsLogicValues,
    insightsFunctionBackfillsLogicActions,
    InsightsFunctionBackfillsLogicProps,
    insightsFunctionBackfillsLogicMeta
>

export const insightsFunctionBackfillsLogic = kea<insightsFunctionBackfillsLogicType>([
    props({} as InsightsFunctionBackfillsLogicProps),
    key(({ id }: InsightsFunctionBackfillsLogicProps) => id),
    path((key) => ['scenes', 'pipeline', 'insightsFunctionBackfillsLogic', key]),
    connect((props: InsightsFunctionBackfillsLogicProps) => ({
        values: [insightsFunctionConfigurationLogic(props), ['configuration']],
        actions: [
            insightsFunctionConfigurationLogic(props),
            ['setConfigurationValues', 'loadInsightsFunction', 'loadInsightsFunctionSuccess'],
        ],
    })),
    actions({
        enableInsightsFunctionBackfills: () => true,
        setLoading: (loading: boolean) => ({ loading }),
    }),
    reducers({
        isLoading: [
            false,
            {
                setLoading: (_, { loading }) => loading,
            },
        ],
        hasTriedEnabling: [
            false,
            {
                enableInsightsFunctionBackfills: () => true,
            },
        ],
    }),
    selectors({
        isReady: [
            (s) => [s.configuration, s.isLoading],
            (configuration: InsightsFunctionConfigurationType, isLoading: boolean) => {
                return !!configuration.batch_export_id && !isLoading
            },
        ],
    }),
    listeners(({ actions, props, values }) => ({
        enableInsightsFunctionBackfills: async () => {
            try {
                actions.setLoading(true)
                await api.insightsFunctions.enableBackfills(props.id)

                // Reload to get the updated config and render <BatchExportBackfills />
                actions.loadInsightsFunction()

                toast.success('Backfills enabled for this destination.')
            } catch {
                toast.error('Failed to enable backfills for this destination.')
            } finally {
                actions.setLoading(false)
            }
        },
        loadInsightsFunctionSuccess: () => {
            // Handle the case where config loads after this logic mounts.
            if (!values.configuration.batch_export_id && !values.hasTriedEnabling) {
                actions.enableInsightsFunctionBackfills()
            }
        },
    })),
    afterMount(({ actions, values }) => {
        // If insightsFunctionConfigurationLogic has already loaded (e.g. user clicked
        // the Backfills tab after the page loaded), check immediately.
        if (values.configuration?.name && !values.configuration.batch_export_id && !values.hasTriedEnabling) {
            actions.enableInsightsFunctionBackfills()
        }
    }),
])
